mapper.select:
SELECT t.id AS task_id, p.repo_full_name AS repo_full_name, p.pr_number AS pr_number, p.title AS pr_title, t.head_sha AS head_sha, t.status AS status, t.stage AS stage, t.progress AS progress, t.report_language AS report_language, CASE WHEN t.head_sha = p.head_sha THEN 0 ELSE 1 END AS is_expired, t.create_time AS create_time, t.finish_time AS finish_time FROM analysis_task t INNER JOIN pull_request p ON p.id = t.pr_id WHERE t.user_id = #{userId} AND t.is_deleted = 0
AND p.repo_full_name = #{query.repo}
AND p.pr_number = #{query.prNumber}
AND t.status = #{query.status}
AND t.create_time >= #{query.startDate}
AND t.create_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)
ORDER BY t.create_time ASC, t.id ASC
ORDER BY t.create_time DESC, t.id DESC
